You already have `error-boundary.tsx`. Here's an enhanced version with more flexibility (render prop, `onError` callback, `onReset` hook, and a `withErrorBoundary` HOC):

```tsx
// my-app/components/ui/error-boundary.tsx
"use client"

import { Component, type ErrorInfo, type ReactNode } from "react"

interface FallbackProps {
  error: Error
  reset: () => void
}

interface ErrorBoundaryProps {
  children: ReactNode
  /** Static fallback node, or a render prop receiving error + reset. */
  fallback?: ReactNode | ((props: FallbackProps) => ReactNode)
  /** Called after React logs the error — use for reporting (Sentry, etc.). */
  onError?: (error: Error, errorInfo: ErrorInfo) => void
  /** Called when the boundary resets. */
  onReset?: () => void
}

interface ErrorBoundaryState {
  hasError: boolean
  error: Error | null
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false, error: null }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error }
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught:", error, errorInfo)
    this.props.onError?.(error, errorInfo)
  }

  reset = () => {
    this.setState({ hasError: false, error: null })
    this.props.onReset?.()
  }

  render() {
    if (!this.state.hasError) return this.props.children

    const { fallback } = this.props
    const { error } = this.state

    if (typeof fallback === "function") {
      return fallback({ error: error!, reset: this.reset })
    }

    if (fallback != null) return fallback

    return (
      <div className="flex flex-col items-center justify-center gap-3 rounded-lg border border-neutral-800 bg-neutral-900 p-6 text-center">
        <p className="text-sm font-medium text-neutral-200">Something went wrong</p>
        <p className="text-xs text-neutral-400">
          {error?.message ?? "An unexpected error occurred."}
        </p>
        <button
          onClick={this.reset}
          className="mt-2 rounded-md bg-neutral-800 px-3 py-1.5 text-xs text-neutral-200 hover:bg-neutral-700"
        >
          Try again
        </button>
      </div>
    )
  }
}

/** Wraps a component in an ErrorBoundary. */
export function withErrorBoundary<P extends object>(
  Component: React.ComponentType<P>,
  boundaryProps?: Omit<ErrorBoundaryProps, "children">
) {
  const Wrapped = (props: P) => (
    <ErrorBoundary {...boundaryProps}>
      <Component {...props} />
    </ErrorBoundary>
  )
  Wrapped.displayName = `withErrorBoundary(${Component.displayName ?? Component.name})`
  return Wrapped
}
```

**What changed from your existing version:**

| Feature | Before | After |
|---|---|---|
| `fallback` | static node only | static node **or** render prop `(error, reset) => ReactNode` |
| `onError` | ❌ | ✅ for external reporting (Sentry, etc.) |
| `onReset` | ❌ | ✅ hook called on reset |
| `withErrorBoundary` HOC | ❌ | ✅ |

**Usage examples:**

```tsx
// Static fallback
<ErrorBoundary fallback={<p>Oops</p>}>
  <MyWidget />
</ErrorBoundary>

// Render prop — access error + reset
<ErrorBoundary fallback={({ error, reset }) => (
  <div>
    <p>{error.message}</p>
    <button onClick={reset}>Retry</button>
  </div>
)}>
  <MyWidget />
</ErrorBoundary>

// HOC
const SafeWidget = withErrorBoundary(MyWidget, { onError: Sentry.captureException })
```
